+export function restoreTicketFilesFromBase(repo: string, baseRef: string): void {
+  try {
+    git(repo, 'reset', 'HEAD', '--', 'team/tickets');
+  } catch {}
+  try {
+    rmSync(join(repo, 'team', 'tickets'), { recursive: true, force: true });
+  } catch {}
+  try {
+    const out = git(repo, 'ls-tree', '-r', '--name-only', '-z', baseRef, '--', 'team/tickets');
+    if (out) {
+      for (const relPath of out.split('\0')) {
+        if (!relPath) continue;
+        const content = git(repo, 'show', `${baseRef}:${relPath}`);
+        const fullPath = join(repo, relPath);
+        mkdirSync(dirname(fullPath), { recursive: true });
+        writeFileSync(fullPath, content, 'utf8');
+      }
+    }
+  } catch {}
+}
+
+function listIgnoredFilesOutsideNodeModules(repo: string): string[] {
+  try {
+    const topEntries = readdirSync(repo).filter((name) => name !== '.git' && name !== 'node_modules');
+    if (topEntries.length === 0) return [];
+    const out = git(repo, 'ls-files', '--others', '-i', '--exclude-standard', '-z', '--', ...topEntries);
+    if (!out) return [];
+    return out
+      .split('\0')
+      .map((p) => p.replace(/\\/g, '/'))
+      .filter(Boolean)
+      .sort();
+  } catch {
+    return [];
+  }
+}
+
+function snapshotNodeModulesBin(repo: string): Record<string, string> {
+  const result: Record<string, string> = {};
+  const binDir = join(repo, 'node_modules', '.bin');
+  if (!existsSync(binDir)) return result;
+
+  function walk(dir: string, prefix: string) {
+    let entries;
+    try {
+      entries = readdirSync(dir, { withFileTypes: true });
+    } catch {
+      return;
+    }
+    for (const ent of entries) {
+      const rel = prefix ? `${prefix}/${ent.name}` : ent.name;
+      const fullPath = join(dir, ent.name);
+      try {
+        const st = lstatSync(fullPath);
+        if (st.isSymbolicLink()) {
+          result[rel] = `symlink:${readlinkSync(fullPath)}`;
+        } else if (st.isDirectory()) {
+          walk(fullPath, rel);
+        } else if (st.isFile()) {
+          const hash = createHash('sha256').update(readFileSync(fullPath)).digest('hex');
+          result[rel] = `file:${hash}`;
+        }
+      } catch {}
+    }
+  }
+
+  walk(binDir, '');
+  return result;
+}
+
+const PKG_MANIFEST_FILES = ['package.json', 'package-lock.json', 'pnpm-lock.yaml', 'yarn.lock'];
+
+function snapshotPkgManifests(repo: string): Record<string, string> {
+  const res: Record<string, string> = {};
+  for (const f of PKG_MANIFEST_FILES) {
+    const p = join(repo, f);
+    if (existsSync(p)) {
+      try {
+        res[f] = createHash('sha256').update(readFileSync(p)).digest('hex');
+      } catch {
+        res[f] = '';
+      }
+    } else {
+      res[f] = '';
+    }
+  }
+  return res;
+}
+
+function didPkgManifestsChange(repo: string, snapshot: TurnGuardSnapshot): boolean {
+  if (!snapshot.pkgManifestHashes) return false;
+  const cur = snapshotPkgManifests(repo);
+  for (const f of PKG_MANIFEST_FILES) {
+    if ((snapshot.pkgManifestHashes[f] ?? '') !== (cur[f] ?? '')) {
+      return true;
+    }
+  }
+  return false;
+}
+
+export function cleanPlantedIgnoredFiles(
+  repo: string,
+  snapshot: TurnGuardSnapshot,
+  seat?: Seat
+): { planted: boolean; cleanedCount: number } {
+  let planted = false;
+  let cleanedCount = 0;
+
+  if (snapshot.ignoredFiles !== undefined) {
+    const preSet = new Set(snapshot.ignoredFiles);
+    const currentIgnored = listIgnoredFilesOutsideNodeModules(repo);
+    for (const relPath of currentIgnored) {
+      if (!preSet.has(relPath)) {
+        cleanedCount++;
+        try {
+          rmSync(join(repo, relPath), { recursive: true, force: true });
+        } catch {}
+      }
+    }
+  }
+
+  // node_modules mới hoàn toàn (vd npm install lần đầu) là hợp lệ – chỉ so .bin khi trước lượt đã có node_modules.
+  if (snapshot.hadNodeModules !== false && snapshot.nodeModulesBin !== undefined && existsSync(join(repo, 'node_modules', '.bin'))) {
+    const currentBin = snapshotNodeModulesBin(repo);
+    const changedBinEntries: string[] = [];
+    for (const [rel, fingerprint] of Object.entries(currentBin)) {
+      if (!Object.hasOwn(snapshot.nodeModulesBin, rel) || snapshot.nodeModulesBin[rel] !== fingerprint) {
+        changedBinEntries.push(rel);
+      }
+    }
+    if (changedBinEntries.length > 0) {
+      const pkgChanged = seat === 'dev' && didPkgManifestsChange(repo, snapshot);
+      if (!pkgChanged) {
+        planted = true;
+        for (const rel of changedBinEntries) {
+          try {
+            rmSync(join(repo, 'node_modules', '.bin', rel), { recursive: true, force: true });
+          } catch {}
+        }
+      }
+    }
+  }
+
+  return { planted, cleanedCount };
+}
