[{"name_path": "listIgnoredFilesOutsideNodeModules", "kind": "Function", "relative_path": "src/core/guard.ts", "body_location": {"start_line": 73, "end_line": 87}, "body": "function listIgnoredFilesOutsideNodeModules(repo: string): string[] {
  try {
    const topEntries = readdirSync(repo).filter((name) => name !== '.git' && name !== 'node_modules');
    if (topEntries.length === 0) return [];
    const out = git(repo, 'ls-files', '--others', '-i', '--exclude-standard', '-z', '--', ...topEntries);
    if (!out) return [];
    return out
      .split('\0')
      .map((p) => p.replace(/\\/g, '/'))
      .filter(Boolean)
      .sort();
  } catch {
    return [];
  }
}"}]

