[{"name_path": "cleanPlantedIgnoredFiles", "kind": "Function", "relative_path": "src/core/guard.ts", "body_location": {"start_line": 97, "end_line": 141}, "body": "export function cleanPlantedIgnoredFiles(
  repo: string,
  snapshot: TurnGuardSnapshot,
  seat?: Seat
): { planted: boolean; cleanedCount: number } {
  let planted = false;
  let cleanedCount = 0;

  if (snapshot.ignoredFiles !== undefined) {
    const preSet = new Set(snapshot.ignoredFiles);
    const currentIgnored = listIgnoredFilesOutsideNodeModules(repo);
    for (const relPath of currentIgnored) {
      if (!preSet.has(relPath)) {
        cleanedCount++;
        try {
          rmSync(join(repo, relPath), { recursive: true, force: true });
        } catch {}
      }
    }
  }

  // node_modules mới hoàn toàn (vd npm install lần đầu) là hợp lệ – chỉ so .bin khi trước lượt đã có node_modules.
  if (snapshot.hadNodeModules !== false && snapshot.nodeModulesBin !== undefined && existsSync(join(repo, 'node_modules', '.bin'))) {
    const currentBin = snapshotNodeModulesBin(repo);
    const changedBinEntries: string[] = [];
    for (const [rel, fingerprint] of Object.entries(currentBin)) {
      if (!Object.hasOwn(snapshot.nodeModulesBin, rel) || snapshot.nodeModulesBin[rel] !== fingerprint) {
        changedBinEntries.push(rel);
      }
    }
    if (changedBinEntries.length > 0) {
      const pkgChanged = seat === 'dev' && didPkgManifestsChange(repo, snapshot);
      if (!pkgChanged) {
        planted = true;
        for (const rel of changedBinEntries) {
          try {
            rmSync(join(repo, 'node_modules', '.bin', rel), { recursive: true, force: true });
          } catch {}
        }
      }
    }
  }

  return { planted, cleanedCount };
}"}]

